method rescale_to_unit(numbers: seq<real>) returns (result: seq<real>)
    requires |numbers| >= 2
    requires forall i :: 0 <= i < |numbers| ==> numbers[i] is real
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] >= 0.0 && result[i] <= 1.0
    ensures result == [if |numbers| > 0 then (numbers[i] - minValue) / (maxValue - minValue) else 0.0 | (i := 0) to |numbers| - 1]
    {
        var minValue := numbers[0];
        var maxValue := numbers[0];

        // Find min and max values
        var n := |numbers|;
        var i := 1;
        while i < n
            invariant 0 <= i <= n
            invariant minValue == Min(numbers[0..i])
            invariant maxValue == Max(numbers[0..i])
        {
            if numbers[i] < minValue {
                minValue := numbers[i];
            }
            if numbers[i] > maxValue {
                maxValue := numbers[i];
            }
            i := i + 1;
        }

        // Rescale the numbers
        var rescaled := new array<real>(n);
        var j := 0;
        while j < n
            invariant 0 <= j <= n
            invariant forall k :: 0 <= k < j ==> rescaled[k] == (numbers[k] - minValue) / (maxValue - minValue)
        {
            rescaled[j] := (numbers[j] - minValue) / (maxValue - minValue);
            j := j + 1;
        }

        result := rescaled;
    }
